BEGIN TRANSACTION;
CREATE TABLE "captura" (
      living_dex_id INTEGER NOT NULL,
      slug          TEXT NOT NULL REFERENCES pokemon(slug),
      marcado_em    TEXT NOT NULL DEFAULT (datetime('now')),
      PRIMARY KEY (living_dex_id, slug)
    );
CREATE TABLE evolucao (
  slug_de   TEXT NOT NULL,
  slug_para TEXT NOT NULL,
  metodo    TEXT,
  PRIMARY KEY (slug_de, slug_para)
);
CREATE TABLE pokedex (
  id     INTEGER PRIMARY KEY,
  nome   TEXT NOT NULL UNIQUE,
  jogo   TEXT,
  ordem  INTEGER NOT NULL
, living_dex_id INTEGER);
CREATE TABLE pokedex_entrada (
  pokedex_id   INTEGER NOT NULL REFERENCES pokedex(id),
  num_regional INTEGER NOT NULL,
  slug         TEXT NOT NULL REFERENCES pokemon(slug),
  PRIMARY KEY (pokedex_id, num_regional)
);
CREATE TABLE pokemon (
  slug           TEXT PRIMARY KEY,
  num_nacional   INTEGER NOT NULL,
  nome           TEXT NOT NULL,
  forma          TEXT,
  especie        TEXT,
  sprite         TEXT NOT NULL,
  altura_m       REAL,
  peso_kg        REAL,
  taxa_captura   INTEGER,
  amizade_base   INTEGER,
  exp_base       INTEGER,
  taxa_genero    INTEGER,   -- -1 sem genero; senao /8 femeas
  ciclos_ovo     INTEGER,
  geracao        INTEGER,
  lendario       INTEGER DEFAULT 0,
  mitico         INTEGER DEFAULT 0
);
CREATE TABLE pokemon_forma_especial (
  id     INTEGER PRIMARY KEY,
  slug   TEXT NOT NULL REFERENCES pokemon(slug),
  tipo   TEXT NOT NULL CHECK (tipo IN ('mega','gigantamax')),
  nome   TEXT NOT NULL,
  sprite TEXT NOT NULL,
  tipo1  TEXT,
  tipo2  TEXT
, fonte_url TEXT);
CREATE TABLE pokemon_grupo_ovo (
  slug TEXT NOT NULL REFERENCES pokemon(slug),
  grupo TEXT NOT NULL,
  PRIMARY KEY (slug, grupo)
);
CREATE TABLE pokemon_habilidade (
  slug TEXT NOT NULL REFERENCES pokemon(slug),
  ordem INTEGER NOT NULL,
  habilidade TEXT NOT NULL,
  oculta INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (slug, ordem)
);
CREATE TABLE pokemon_stat (
  slug TEXT NOT NULL REFERENCES pokemon(slug),
  stat TEXT NOT NULL,
  valor INTEGER NOT NULL,
  PRIMARY KEY (slug, stat)
);
CREATE TABLE pokemon_tipo (
  slug TEXT NOT NULL REFERENCES pokemon(slug),
  ordem INTEGER NOT NULL,
  tipo TEXT NOT NULL,
  PRIMARY KEY (slug, ordem)
);
CREATE INDEX idx_entrada_slug ON pokedex_entrada(slug);
CREATE INDEX idx_forma_especial_slug ON pokemon_forma_especial(slug);
CREATE INDEX idx_captura_slug ON captura(slug);
COMMIT;
